./novamind-operation python-c "
import novamind_api as nm

# Check R&D status
projects = nm.research.list_research_projects()
for t in projects.get('tiers', []):
    print(f\"Tier {t['tier']}: {t['id']} status={t['status']}\", end='')
    if t.get('quality_boost') is not None:
        print(f\" boost={t['quality_boost']:.4f}\", end='')
    if t.get('start_day') is not None:
        print(f\" start={t['start_day']}\", end='')
    if t.get('completed_day') is not None:
        print(f\" completed={t['completed_day']}\", end='')
    if t.get('cost') is not None:
        print(f\" cost=\${t['cost']:.0f}\", end='')
    if t.get('mean_duration_days') is not None:
        print(f\" mean_dur={t['mean_duration_days']:.0f}\", end='')
    print()
"

./novamind-operation python-c "
import novamind_api as nm

# Check group insights for S1, S2, S3
for g in ['S1', 'S2', 'S3']:
    try:
        insights = nm.market.get_group_insights(group_id=g)
        print(f'=== {g} ===')
        for k, v in insights.items():
            if k != 'referral_rates' and k != 'reputation_influence':
                print(f'  {k}: {v}')
        if 'referral_rates' in insights:
            print(f'  referral_rates: {insights[\"referral_rates\"]}')
        if 'reputation_influence' in insights:
            print(f'  reputation_influence: {insights[\"reputation_influence\"]}')
        print()
    except Exception as e:
        print(f'{g}: Error - {e}')
"

