./novamind-operation python-c "
import novamind_api as nm

# Social posts - check competitor events
posts = nm.analytics.get_social_posts(days=14, limit=30)
print('=== Social Posts (Last 14 days) ===')
for p in posts['posts'][:20]:
    print(f\"Day {p['day']}: [{p['source_type']}] {p['content'][:120]}\")

# Check market overview
overview = nm.market.get_market_overview()
print('\n=== Market Overview ===')
if 'groups' in overview:
    for g in overview['groups'][:10]:
        print(g)
elif isinstance(overview, dict):
    for k, v in overview.items():
        if k != 'groups':
            print(f'{k}: {v}')
"

./novamind-operation python-c "
import novamind_api as nm

# Check group insights for S1
insights = nm.market.get_group_insights(group_id='S1')
print('=== S1 Group Insights ===')
for k, v in insights.items():
    if k not in ['referral_rates', 'reputation_influences']:
        print(f'{k}: {v}')
    elif k == 'referral_rates':
        print('Referral rates:')
        for r in v[:10]:
            print(f'  {r}')
    elif k == 'reputation_influences':
        print('Reputation influences:')
        for r in v[:10]:
            print(f'  {r}')

print(f'\nCurrent day: {nm.vars.current_day}')
"

